class Solution {
    private class Fenwick(n:Int){
        val tree=IntArray(n+1);
        fun add(index:Int,delta:Int){
            var i=index+1;
            while(i<tree.size){
                tree[i]+=delta;
                i+=i and -i
            }
        };
        fun query(index:Int):Int{
            var i=index+1;
            var sum=0;
            while(i>0){
                sum+=tree[i];
                i-=i and -i
            };
            return sum
        }
    };
    fun minInteger(num:String,kValue:Int):String{
        val positions=Array(10){
            java.util.ArrayDeque<Int>()
        };
        val fenwick=Fenwick(num.length);
        for(i in num.indices){
            positions[num[i]-'0'].addLast(i);
            fenwick.add(i,1)
        };
        var k=kValue;
        val answer=StringBuilder();
        repeat(num.length){
            for(digit in 0..9)if(positions[digit].isNotEmpty()){
                val position=positions[digit].peekFirst();
                val cost=fenwick.query(position)-1;
                if(cost<=k){
                    k-=cost;
                    answer.append(digit);
                    positions[digit].removeFirst();
                    fenwick.add(position,-1);
                    break
                }
            }
        };
        return answer.toString()
    }
}

